<form method="post" class="form-card stack"><input type="hidden" name="_token" value="<?=e(Csrf::token())?>"><label>氏名 <span>必須</span><input type="text" name="name" value="<?=e((string)$data['name'])?>" maxlength="100" required><?php if(isset($errors['name'])):?><small class="error"><?=e($errors['name'])?></small><?php endif;?></label><label>メールアドレス <span>必須</span><input type="email" name="email" value="<?=e((string)$data['email'])?>" maxlength="255" required><?php if(isset($errors['email'])):?><small class="error"><?=e($errors['email'])?></small><?php endif;?></label><div class="form-grid"><label>電話番号<input name="phone" value="<?=e((string)$data['phone'])?>" maxlength="30"><?php if(isset($errors['phone'])):?><small class="error"><?=e($errors['phone'])?></small><?php endif;?></label><label>会社名<input name="company" value="<?=e((string)$data['company'])?>" maxlength="120"><?php if(isset($errors['company'])):?><small class="error"><?=e($errors['company'])?></small><?php endif;?></label></div><button class="button button-primary">保存する</button></form>